import std.io

record Pair<A, B> { first: A, second: B }
pub type AppError = Failed(String)
pub fn main() effect io -> Result<(), AppError> {
    let p1 = Pair { first: 1, second: "a" }
    let p2 = Pair<Int64, String> { first: 2, second: "b" }
    io.println("${p1.first}${p1.second}${p2.first}${p2.second}")
    return Ok(())
}
